    for i in range(n): 

        // Find the smallest element 
        min_idx = i 
        for j in range(i+1, n): 
            if A[j] < A[min_idx]: 
                min_idx = j 

        // Swap the found smallest element 
        A[i], A[min_idx] = A[min_idx], A[i] 

def sort(A): 
