void convertMarkdownToHtml(std::string& markdown)
{
    std::string html;
    const char* markdown_syntax = "%markdown syntax%";
    const char* html_syntax = "%html syntax%";

    // Go through each character of the markdown string and if it is a character
    // that has a corresponding html syntax, replace the markdown character with the
    // corresponding html syntax
    for (int i = 0; i < markdown.length(); i++)
    {
        if (markdown[i] == '*')
        {
            html += " ";
            html += " ";
        }
        else if (markdown[i] == '(')
        {
            html += "<p>";
        }
        else if (markdown[i] == ')' || markdown[i] == '>')
        {
            html += "</p>";
        }
        else if (markdown[i] == markdown_syntax)
        {
            html += html_syntax;
        }
        else
        {
            html += markdown[i];
        }
    }

    // Return the converted html string
    return html;
}

