def binary_search(arr, element):
    low = 0
    high = len(arr) - 1

    while low <= high:
        mid = (low + high) // 2
        if element == arr[mid]:
            return mid
        if element < arr[mid]:
            low = mid + 1
        else:
            high = mid - 1

    return -1

