def longestCommonSubsequence(a, b): 
    a = sorted(list(a)) 
    b = sorted(list(b)) 
    dp = [[0] * (len(a) + 1) + [0]] 
    for i in range(len(a)): 
        for j in range(i + 1, len(a)): 
            if a[i] == b[j]: 
                dp[i][j] = dp[i - 1][j - 1] + 1
        dp[i][len(b)] = max(dp[i - 1][len(a)] + 1, 
                             dp[i][len(a)] + 1 ) 
    return dp[len(a)][len(b)] 

