def derivative(x):
    """This function takes in a variable x and outputs the derivative using
    The Average Rate of Change Formula A(x) = f(b)-f(a) /(b-a).
    """
    # Get the initial value and final value of the function
    initial_value = 0
    final_value = 0
    if x > 0:
        initial_value = 1
    else:
        initial_value = -1
    for i in range(1, x+1):
        current_value = 0
        for j in range(i, x+1):
            current_value += (final_value - initial_value)/(x-j+1)
        final_value = current_value
    return current_value

