// Function to convert markdown text to html text
std::string convertMarkdownToHtml(std::string markdownText)
{
    // Get the appropriate markdown syntax highlighting library
    std::string::size_type pos = 0;
    std::string::size_type end = markdownText.find("```", pos);
    if (end == std::string::npos)
    {
        return markdownText;
    }
    else
    {
        // Extract the code block
        std::string codeBlock = markdownText.substr(pos, end - pos + 6);
        // Find the appropriate closing tag
        pos = codeBlock.rfind("```");
        if (pos == -1)
        {
            return markdownText;
        }
        else
        {
            // Add a trailing newline after the closing tag
            codeBlock += "\n";
            // Return the modified text
            return codeBlock;
        }
    }
}

