boolean isPowerOfThree(int n) {
 // If n is negative, it's not a power of three.
 if (n < 0) {
 return false;
 }
 // If n is 0, it's not a power of three.
 if (n == 0) {
 return false;
 }
 // If n is positive, find the smallest x such that 3^x = n.
 int smallestX = n;
 while (smallestX > 0) {
 smallestX = smallestX / 3;
 }
 // If smallestX is 1 or 2, then n is not a power of three.
 if (smallestX == 1 || smallestX == 2) {
 return false;
 }
 // Otherwise, n is a power of three.
 return true;
}

