  for (let i = 0; i < numbers.length; i++) {
    let num = numbers[i];
    let isPrime = true;

    for (let j = 2; j < num; j++) {
      if (num % j === 0) {
        isPrime = false;
        break;
      }
    }

    if (isPrime) {
      console.log(num);
    }
  }
}

